import{_ as p,a0 as s,w as l,s as i,ao as a,I as r,a1 as n,A as u,x as o}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"如何从Ubuntu的声音菜单中移除音乐播放器 | LCTT x X-CMD","titleTemplate":false,"description":"如何从Ubuntu的声音菜单中移除音乐播放器 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何从Ubuntu的声音菜单中移除音乐播放器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何从Ubuntu的声音菜单中移除音乐播放器 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu","title":"如何从Ubuntu的声音菜单中移除音乐播放器","tag":"201412","desc":""},"relativePath":"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu.md","filePath":"[post].md"}'),d={name:"201412/20141112 How to Remove Music Players from Ubuntu Sound Menu.md"};function m(b,t,f,g,w,T){const e=s("Link");return l(),i("div",null,[t[14]||(t[14]=a('<h1 id="如何从ubuntu的声音菜单中移除音乐播放器" tabindex="-1">如何从Ubuntu的声音菜单中移除音乐播放器 <a class="header-anchor" href="#如何从ubuntu的声音菜单中移除音乐播放器" aria-label="Permalink to “如何从Ubuntu的声音菜单中移除音乐播放器”">​</a></h1><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/music-players.jpg" alt=""></p><p><strong>自从2010年首次出现，Ubuntu 的声音菜单已经被证明是Unity 桌面上的最流行的独有特性之一。</strong></p><p>把音乐播放器与音量控制程序集成到一个标准的界面里是一种看起来很聪明的做法，这样就不用到处找声音相关的各种程序。人们不禁要问，为什么其它操作系统没有效仿这种做法！</p><h4 id="臃肿" tabindex="-1">臃肿 <a class="header-anchor" href="#臃肿" aria-label="Permalink to “臃肿”">​</a></h4><p>尽管它看起来很方便，但是这个小应用当前存在一个问题：很多播放器都堆在一起，像一个组合音响一样。也许你用得着，但是你安装的所有的媒体播放器都挤在这里，这会让人看着很累赘和反感。</p><p>我将要打赌，当你读到这里时，一定发现上面的截图看起来很熟悉！不要担心，<strong>dconf-editor</strong>可以解决它。</p><h3 id="从ubuntu-声音菜单中移除播放器" tabindex="-1">从Ubuntu 声音菜单中移除播放器 <a class="header-anchor" href="#从ubuntu-声音菜单中移除播放器" aria-label="Permalink to “从Ubuntu 声音菜单中移除播放器”">​</a></h3><h4 id="第一部分-基础知识" tabindex="-1">第一部分: 基础知识 <a class="header-anchor" href="#第一部分-基础知识" aria-label="Permalink to “第一部分: 基础知识”">​</a></h4><p>最快速和最简单地从声音菜单中移除播放器的方法就是卸载相关的应用程序。但这是极端的方式，我的意思是指你也许想要保留应用程序，但是不需要它集成到菜单里面。</p><p>只删除播放器但是保留我们需要的应用程序，我们用到一个看起来令人惊讶的工具叫“dconf-editor”。</p><p>你可能已经安装了，如果没有安装的话，那么你从Ubuntu软件中心找出。</p>',12)),r("ul",null,[r("li",null,[n(e,{href:"apt://dconf-editor"},{default:u(()=>[...t[0]||(t[0]=[o("在Ubuntu中点击安装Dconf-Editor",-1)])]),_:1})])]),t[15]||(t[15]=a(`<p>一旦安装完毕，找到Unity Dash并打开。打开的时候不要惊慌；你没有到2002年，它确实是这种古老的样子。</p><p>使用右侧菜单栏，你需要从导航到 com &gt; canonical &gt; indicator &gt; sound.下面的面板将会出现。</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/dconf-editor.jpg" alt=""></p><p>双击“interested-media-players”旁的闭括号，并删除你希望从声音菜单里移除掉的播放器，但需要保留方括号中，且不要删除任何需要保留的逗号或者单引号。</p><p>举个例子，我移除掉这些</p><p>‘<strong>rhythmbox.desktop</strong>’, ‘<strong>pithos.desktop</strong>’, ‘<strong>clementine.desktop</strong>’,</p><p>这样就好留了一行如下：</p><pre><code>[&#39;tomahawk.desktop&#39;]
</code></pre><p>现在，当我再打开声音菜单时，我只看到Tomahawk:</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/11/music-players-2.jpg" alt=""></p><h4 id="第二部分-黑名单" tabindex="-1">第二部分：黑名单 <a class="header-anchor" href="#第二部分-黑名单" aria-label="Permalink to “第二部分：黑名单”">​</a></h4><p>等等！还不能关闭dconf-editor。尽管上面的步骤看起来把事情处理得干净利落，但是一些播放器在打开时会立即重新加载到声音菜单。为了避免重复这个过程，将它们添加到<strong>blacklisted-media-player</strong>中。</p><p>记得每个在括号里的播放器都用逗号分隔多个条目。他们也必须在方括号内，所以在退出之前请务必仔细检查。</p><p>最终结果如下：</p><p><img src="http://www.omgubuntu.co.uk/wp-content/uploads/2014/10/from-to-.jpg" alt=""></p><hr>`,16)),r("p",null,[t[2]||(t[2]=o("via: ",-1)),n(e,{href:"http://www.omgubuntu.co.uk/2014/11/remove-players-ubuntu-sound-menu"},{default:u(()=>[...t[1]||(t[1]=[o("http://www.omgubuntu.co.uk/2014/11/remove-players-ubuntu-sound-menu",-1)])]),_:1})]),r("p",null,[t[6]||(t[6]=o("作者：",-1)),n(e,{href:"https://plus.google.com/117485690627814051450/?rel=author"},{default:u(()=>[...t[3]||(t[3]=[o("Joey-Elijah Sneddon",-1)])]),_:1}),t[7]||(t[7]=o(" 译者：",-1)),n(e,{href:"https://github.com/%E8%AF%91%E8%80%85ID"},{default:u(()=>[...t[4]||(t[4]=[o("disylee",-1)])]),_:1}),t[8]||(t[8]=o(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:u(()=>[...t[5]||(t[5]=[o("wxy",-1)])]),_:1})]),r("p",null,[t[11]||(t[11]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:u(()=>[...t[9]||(t[9]=[o("LCTT",-1)])]),_:1}),t[12]||(t[12]=o(" 原创翻译，",-1)),n(e,{href:"http://linux.cn/"},{default:u(()=>[...t[10]||(t[10]=[o("Linux中国",-1)])]),_:1}),t[13]||(t[13]=o(" 荣誉推出",-1))])])}const x=p(d,[["render",m]]);export{_ as __pageData,x as default};
